import "./src/lib/env/load-local-env.ts";
import { defineConfig } from "drizzle-kit";

/**
 * Tretu platform schema only (Postgres). Development/tests: `npm run platform:db:push`.
 * Production migrations are generated by the integrator for the merged schema.
 */
export default defineConfig({
  schema: "./src/db/platform-schema.ts",
  out: "./drizzle-platform",
  dialect: "postgresql",
  dbCredentials: {
    url: process.env.DATABASE_URL ?? "postgres://postgres@localhost:5432/tretu_platform",
  },
  tablesFilter: ["platform_*"],
});
